import { ink, type PortraitProps } from './types';

/**
 * Paintable Mary, Mother of God portrait traced from the generated line art.
 *
 * Expected parent SVG viewBox: 0 0 640 700
 * The paint masks are interactive; the exact monochrome outline is rendered last
 * with pointerEvents='none', so it never blocks painting clicks.
 */
const ART_TRANSFORM =
  'matrix(0.5416 0 0 0.5416 -72.11 61)';

// The generated line art carries its own traced picture frame (a ~7 unit ring
// around the panel). SaintArt already draws the card outline, so clipping the
// ink to just inside that ring removes the doubled inner border.
const PANEL_CLIP_ID = 'mary-panel-clip';

function splitVectorPaths(pathData: string) {
  return pathData
    .split(/(?=M)/g)
    .map((path) => path.trim())
    .filter(Boolean);
}

