export default function MaryMotherOfGod({ p, detail }: PortraitProps) {
  const cloudPaint = p('cloud');
  const haloPaint = p('halo');
  const symbolPaint = p('symbol');
  const mantlePaint = p('mantle');
  const robePaint = p('robe');
  const accentPaint = p('accent');
  const hairPaint = p('hair');
  const skinPaint = p('skin');

  const cloudVectors = splitVectorPaths(CLOUD_MASK);
  const robeVectors = splitVectorPaths(ROBE_MASK);
  const accentVectors = splitVectorPaths(ACCENT_MASK);
  const hairVectors = splitVectorPaths(HAIR_MASK);
  const skinVectors = splitVectorPaths(SKIN_MASK);
  const symbolVectors = splitVectorPaths(SYMBOL_MASK);

  return (
    <>
      <g transform={ART_TRANSFORM}>
        <defs>
          <clipPath id={PANEL_CLIP_ID}>
            <rect x="161" y="29" width="1126" height="1029" rx="60" ry="60" />
          </clipPath>
        </defs>

        <path {...cloudPaint} d={CLOUD_GAPS} fillRule="evenodd" />

        {/*
          Every cloud vector belongs to the single 'cloud' region. They all
          share the same paint props so they fill together and — crucially —
          are actually clickable: RegionId (and Saint.regions) only knows the
          canonical region names, so per-vector ids like "mary-cloud-3" never
          matched anything and silently ate every click.
        */}
        {cloudVectors.map((d, index) => (
          <path
            key={`cloud-${index}`}
            {...cloudPaint}
            d={d}
            fillRule="evenodd"
          />
        ))}

        {/* Halo ring: outer subpath, then the inner hole (even-odd). */}
        <g {...haloPaint}>
          <path fillRule="evenodd" d={HALO_GAPS} />
          <path fillRule="evenodd" d={HALO_MASK} />
        </g>

        <path {...symbolPaint} d={SYMBOL_GAPS} fillRule="evenodd" />

        {/* Every star/symbol vector belongs to the single 'symbol' region. */}
        {symbolVectors.map((d, index) => (
          <path
            key={`symbol-${index}`}
            {...symbolPaint}
            d={d}
            fillRule="evenodd"
          />
        ))}

        <path {...mantlePaint} d={MANTLE_GAPS} fillRule="evenodd" />

        {/* This is one SVG vector for the mantle region. */}
        <path
          {...mantlePaint}
          d="M560 500C500 525 430 565 390 625L372 665L358 710L348 755L344 800L340 845L332 890L324 935L316 978L310 1060L1078 1060L1070 978L1064 940L1056 895L1046 850L1034 805L1018 755L1004 710L992 665L985 625C940 565 850 525 888 500C852 532 814 553 780 565H668C634 553 596 532 560 500Z"
        />

        {/* Main robe vector. */}
        <path
          {...robePaint}
          d="M584 486C626 521 676 539 724 539C772 539 822 521 864 486L894 957L902 1060L546 1060L554 957Z"
        />

        <path {...robePaint} d={ROBE_GAPS} fillRule="evenodd" />

        {/* Every remaining robe vector belongs to the same 'robe' region. */}
        {robeVectors.map((d, index) => (
          <path
            key={`robe-${index}`}
            {...robePaint}
            d={d}
            fillRule="evenodd"
          />
        ))}

        <path {...accentPaint} d={ACCENT_GAPS} fillRule="evenodd" />

        {/* Every accent vector belongs to the single 'accent' region. */}
        {accentVectors.map((d, index) => (
          <path
            key={`accent-${index}`}
            {...accentPaint}
            d={d}
            fillRule="evenodd"
          />
        ))}

        <path {...hairPaint} d={HAIR_GAPS} fillRule="evenodd" />

        {/* Every hair vector belongs to the single 'hair' region. */}
        {hairVectors.map((d, index) => (
          <path
            key={`hair-${index}`}
            {...hairPaint}
            d={d}
            fillRule="evenodd"
          />
        ))}

        <path {...skinPaint} d={SKIN_GAPS} fillRule="evenodd" />

        {/* Every skin vector belongs to the single 'skin' region. */}
        {skinVectors.map((d, index) => (
          <path
            key={`skin-${index}`}
            {...skinPaint}
            d={d}
            fillRule="evenodd"
          />
        ))}

        {/* Exact black line-art overlay; deliberately non-interactive. The clip
            trims the traced picture frame so only SaintArt's card outline shows. */}
        <g clipPath={`url(#${PANEL_CLIP_ID})`}>
          <path
            {...detail}
            {...ink}
            d={MARY_LINE_ART}
            fillRule="evenodd"
          />
        </g>
      </g>
    </>
  );
}
